import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Iridium","description":"","frontmatter":{"title":"Iridium","order":2},"headers":[],"relativePath":"zh/mods/iridium.md","filePath":"zh/mods/iridium.md","lastUpdated":1786943111000}'),l={name:"zh/mods/iridium.md"};function o(d,a,n,s,h,u){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="iridium" tabindex="-1">Iridium <a class="header-anchor" href="#iridium" aria-label="Permalink to &quot;Iridium&quot;">​</a></h1><blockquote><p>面向《冰与火之舞》的<strong>优化 Mod</strong>，聚焦性能、视觉自定义与兼容性。</p><p>项目地址：<a href="https://github.com/adofaiex/Iridium" target="_blank" rel="noreferrer">https://github.com/adofaiex/Iridium</a></p></blockquote><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><ul><li>渲染效率优化，减少卡顿</li><li>装饰纹理压缩、逐帧加载（带进度）</li><li>Move Track / Move Decorations 优化（支持 freeroam）</li><li>粒子优化（对象池 / 剔除 / LOD）</li><li>DOTween 调优、自定义缓动引擎</li><li>异步输入优化，提升判定精度</li></ul><h3 id="界面与视觉" tabindex="-1">界面与视觉 <a class="header-anchor" href="#界面与视觉" aria-label="Permalink to &quot;界面与视觉&quot;">​</a></h3><ul><li>移除新闻面板、隐藏测试版水印、调整自动演示文本位置</li><li>编辑器显示倒计时</li><li>大厅音乐：按 BPM 切换背景音乐，支持自定义音乐路径</li><li>判定文本自定义（如「Perfect」「Too Early」），支持富文本标签与偏移显示</li><li>打击音效音高跟随音乐</li></ul><h3 id="编辑器增强" tabindex="-1">编辑器增强 <a class="header-anchor" href="#编辑器增强" aria-label="Permalink to &quot;编辑器增强&quot;">​</a></h3><ul><li>大关卡（1 万+ 地板）的插入/删除操作性能优化</li><li>装饰与地板的自定义快捷键</li><li>自动演示预览支持暂停 / 恢复</li></ul><h3 id="兼容性与修复" tabindex="-1">兼容性与修复 <a class="header-anchor" href="#兼容性与修复" aria-label="Permalink to &quot;兼容性与修复&quot;">​</a></h3><ul><li>忽略缺失的三方 Mod 依赖加载谱面（保存时恢复 <code>requiredMods</code>）</li><li>未知自定义事件（CustomEvent）临时注册，避免加载崩溃</li><li>旧版本关卡行为选项（Flash、Camera Relative 等）</li><li>修复传送门软锁、发卡弯节拍检测、编辑器回放错误追踪</li></ul><h3 id="补丁模式" tabindex="-1">补丁模式 <a class="header-anchor" href="#补丁模式" aria-label="Permalink to &quot;补丁模式&quot;">​</a></h3><ul><li><strong>IL Transpiler</strong>：性能优先</li><li><strong>Prefix/Postfix</strong>：兼容优先</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h3><ul><li>已安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a></li><li>已安装 ADOFAI</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>ADOFAI 2.10.0 及以上版本请使用 <strong>UnityModManager 0.32.5.0 或更高</strong>，否则可能崩溃。</p></div><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>前往 <a href="https://github.com/Xbodwf/Iridium/releases" target="_blank" rel="noreferrer">Releases</a>，下载<strong>与你游戏版本匹配</strong>的构建（每个 Release 提供多个版本的构建）</li><li>解压到 <code>A Dance of Fire and Ice/Mods/Iridium</code>（目录不存在则创建）</li><li>启动游戏；若游戏已在运行，请先重启</li></ol><h3 id="支持的游戏版本" tabindex="-1">支持的游戏版本 <a class="header-anchor" href="#支持的游戏版本" aria-label="Permalink to &quot;支持的游戏版本&quot;">​</a></h3><table tabindex="0"><thead><tr><th>游戏版本</th><th>分支</th></tr></thead><tbody><tr><td>ADOFAI v2</td><td><code>v2</code> 分支</td></tr><tr><td>ADOFAI v3</td><td><code>v3</code> 分支</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>除专门为旧版本游戏调校的版本外，请勿在 ADOFAI <strong>2.9.7 及以下</strong>运行 Iridium。</p></div><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>启动后在 UMM 设置界面（默认 <code>Ctrl+F10</code>）中，v3 的设置按 <strong>General / Optimizer / Editor / Compatibility / Audio</strong> 分页展示。</p><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><blockquote><p>📝 待补充（欢迎在仓库 Issues 中反馈）</p></blockquote><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>其他加载方式：<a href="https://github.com/Xbodwf/Iridium/blob/main/docs/loader/melonloader.md" target="_blank" rel="noreferrer">MelonLoader</a> / <a href="https://github.com/Xbodwf/Iridium/blob/main/docs/loader/bepinex.md" target="_blank" rel="noreferrer">BepInEx</a></li></ul>',28)])])}const b=e(l,[["render",o]]);export{m as __pageData,b as default};
